window.PET_DATA["knowledge/phrases-opinion.json"] = {"id":"phrases-opinion","type":"phrases","title":"Phrases: Giving Opinions","topic":"opinion","objective":"Express, support and politely challenge opinions in Writing Part 2 and Speaking Parts 3–4.","sections":[{"heading":"How to use these","body":"In the exam you are scored for **giving and justifying** opinions, not just stating them. Always follow an opinion phrase with a reason (`because`, `so`, examples).\nIn Writing Part 2, use 2–3 different opinion structures across the text, e.g. `In my opinion...` in the introduction and `All in all...` in the conclusion.","bodyZh":"考试评分看的是你能否给出并论证观点，而不只是表态。观点句后面一定要接理由或例子。写作第二部分可在开头用 In my opinion，结尾用 All in all。","tip":"Never write just I think in an article — examiners reward the fuller phrases."}],"items":[{"id":"p_op_001","phrase":"In my opinion, …","meaning":"used to introduce your view","meaningZh":"在我看来……","example":"In my opinion, school trips should be longer.","exampleZh":"在我看来，学校旅行应该更长一些。"},{"id":"p_op_002","phrase":"I think / I don't think (that)…","meaning":"the simplest way to give a view","meaningZh":"我认为／我不认为……","example":"I think learning languages is great fun.","exampleZh":"我觉得学语言很有趣。"},{"id":"p_op_003","phrase":"I believe (that)…","meaning":"a slightly stronger opinion","meaningZh":"我相信……","example":"I believe everyone should learn first aid.","exampleZh":"我相信每个人都应该学急救。"},{"id":"p_op_004","phrase":"From my point of view, …","meaning":"a formal way to introduce your view","meaningZh":"从我的角度来看……","example":"From my point of view, the film was too long.","exampleZh":"从我的角度看，这部电影太长了。"},{"id":"p_op_005","phrase":"As far as I'm concerned, …","meaning":"used to stress it is YOUR opinion","meaningZh":"就我而言……","example":"As far as I'm concerned, cycling is the best way to travel.","exampleZh":"就我而言，骑车是最好的出行方式。"},{"id":"p_op_006","phrase":"I agree up to a point, but …","meaning":"partial agreement before disagreeing","meaningZh":"我部分同意，但是……","example":"I agree up to a point, but homework is still important.","exampleZh":"我部分同意，但作业仍然重要。"},{"id":"p_op_007","phrase":"I see what you mean, but …","meaning":"polite disagreement","meaningZh":"我明白你的意思，但是……","example":"I see what you mean, but I'd choose the other option.","exampleZh":"我明白你的意思，但我会选另一个。"},{"id":"p_op_008","phrase":"I couldn't agree more.","meaning":"total agreement","meaningZh":"我完全同意。","example":"You're right about the museum — I couldn't agree more.","exampleZh":"你对博物馆的看法我很赞同——我完全同意。"},{"id":"p_op_009","phrase":"That's a good point.","meaning":"accepting someone's idea","meaningZh":"说得好。","example":"That's a good point. We should leave earlier.","exampleZh":"说得好。我们应该早点出发。"},{"id":"p_op_010","phrase":"It depends on …","meaning":"used when the answer is not fixed","meaningZh":"这取决于……","example":"It depends on the weather.","exampleZh":"这要看天气。"},{"id":"p_op_011","phrase":"On the one hand … on the other hand …","meaning":"comparing two sides of an argument","meaningZh":"一方面……另一方面……","example":"On the one hand, phones are useful; on the other hand, they waste time.","exampleZh":"一方面手机很有用；另一方面它们浪费时间。"},{"id":"p_op_012","phrase":"All in all, …","meaning":"used to give a final conclusion","meaningZh":"总而言之……","example":"All in all, it was a wonderful holiday.","exampleZh":"总而言之，那是一次很棒的假期。"}],"summary":{"keyPoints":["Opinion + reason + example = a complete answer.","Vary your phrases: don't repeat I think.","Polite disagreement keeps Speaking Part 4 flowing."],"mustKnow":["In my opinion","I see what you mean, but","I couldn't agree more","All in all"]},"linkedPractice":["speaking","writing"],"reviewItems":["p_op_001","p_op_002","p_op_003","p_op_004","p_op_005","p_op_006","p_op_007","p_op_008","p_op_009","p_op_010","p_op_011","p_op_012"]};
